with unpacked as (select id, customer_id, created_at, coupon_codes, items, array_join(array_sort(coupon_codes), ',') as coupons_text, exists(coupon_codes, c -> c like 'W%') as has_welcome_code, array_max(transform(items, x -> x.price)) as max_item_price, exists(items, x -> x.price > 100) as has_premium_item, ship_to.zip as ship_zip from carts where array_contains(coupon_codes, 'WELCOME5')) select id, customer_id, created_at, coupons_text, has_welcome_code, ship_zip, sum(max_item_price) over (order by created_at, id rows between unbounded preceding and current row) cumulative_max_item_price, sum(max_item_price) over w_part cumulative_max_item_price_2, avg(max_item_price) over (partition by customer_id order by max_item_price, id rows between 5 preceding and current row) max_item_price_avg_5, avg(max_item_price) over (partition by customer_id order by max_item_price, id rows between 5 preceding and 1 preceding) max_item_price_avg_5_prior from unpacked where size(coupon_codes) >= 2 window w_part as (partition by customer_id order by created_at, id rows between unbounded preceding and current row);
